// Fusionne les données des deux requêtes précédentes
const all = $input.all();

// Articles veille (premier item = tableau)
let articles = [];
for (const item of all) {
  if (Array.isArray(item.json)) {
    articles = item.json.slice(0, 3);
  }
}

// Insight Anna (dernier item)
let insight = null;
for (const item of all) {
  if (item.json.semaine) insight = item.json;
}

// Formater les articles pour le prompt
const articlesText = articles.length > 0
  ? articles.map((a, i) => `${i+1}. [${a.source}] ${a.titre}\n   ${a.resume || ''}`.trim()).join('\n\n')
  : 'Pas d\'article veille disponible cette semaine.';

// Formater les insights Anna
let insightText = 'Pas encore de check-in cette semaine.';
if (insight) {
  const parts = [];
  if (insight.reponse_1) parts.push(`• ${insight.reponse_1}`);
  if (insight.reponse_2) parts.push(`• ${insight.reponse_2}`);
  if (insight.reponse_3) parts.push(`• ${insight.reponse_3}`);
  if (parts.length) insightText = parts.join('\n');
}

const veille_ids = articles.map(a => a.id).filter(Boolean);
const insight_id = insight?.id || null;

const prompt = `Tu es Anna Leroulier, fondatrice de CNL Sourcing, agence de sourcing France-Vietnam spécialisée en textile, agroalimentaire et artisanat pour les PME françaises. Tu vis entre la France et le Vietnam.

Ton style LinkedIn : professionnel mais chaleureux, direct, ancré dans l'expérience terrain. Tu partages des insights concrets, jamais du marketing creux. Tes posts génèrent de l'engagement parce qu'ils sont vrais.

--- CONTEXTE ACTUALITÉ (à intégrer subtilement) ---
${articlesText}

--- TON VÉCU CETTE SEMAINE ---
${insightText}

--- INSTRUCTIONS ---
Écris un post LinkedIn en français de 180-280 mots.

Structure OBLIGATOIRE :
1. Accroche forte (1-2 lignes, pose une question ou fait une affirmation surprenante)
2. Corps : 1-2 insights tirés de l'actualité ET de ton expérience, liés naturellement (pas de "j'ai lu un article que...")
3. Conclusion : enseignement ou conseil actionnable
4. CTA naturel (1 ligne, ex: "Vous importez depuis le Vietnam ? Parlons-en.")
5. 4-6 hashtags pertinents sur une nouvelle ligne

Ne mentionne pas les sources directement. Intègre les infos comme si c'était ta propre observation de terrain.
Si le vécu d'Anna est vide, invente un scénario crédible basé sur l'actualité seule.`;

return [{ json: { prompt, veille_ids, insight_id } }];

const resp   = $input.first().json;
const contenu = resp.content?.[0]?.text?.trim() || '';
const tokens  = (resp.usage?.input_tokens || 0) + (resp.usage?.output_tokens || 0);
const prev    = $('Construire prompt Claude').first().json;
return [{ json: {
  contenu,
  tokens_utilises: tokens,
  modele_utilise: 'claude-sonnet-4-6',
  veille_ids: prev.veille_ids,
  insight_id: prev.insight_id
} }];

